PLANO_A_ROGERS_SATCHELL.codigo_mql5_implementacao:
// Adicionar em arquivo Include/RogersS atchell.mqh
double CalculateRogersS atchell(string symbol, ENUM_TIMEFRAMES tf, int period) {
    double high[], low[], close[];
    if(CopyHigh(symbol, tf, 0, period+1, high) != period+1) return 0;
    if(CopyLow(symbol, tf, 0, period+1, low) != period+1) return 0;
    if(CopyClose(symbol, tf, 0, period+1, close) != period+1) return 0;

    double sum = 0;
    for(int i = 0; i < period; i++) {
        if(high[i] <= 0 || close[i] <= 0 || low[i] <= 0) continue;
        double term1 = MathLog(high[i] / close[i]);
        double term2 = MathLog(low[i] / close[i]);
        sum += term1 * term1 + term2 * term2;
    }

    return MathSqrt(sum / period);
}

PLANO_B_SATR_BLEND.codigo_mql5_implementacao:
double CalculateSATR Blend(string symbol, ENUM_TIMEFRAMES tf, int atr_period, int smooth) {
    // 1. Calcular SATR
    int atr_handle = iATR(symbol, tf, atr_period);
    double atr_buffer[];
    if(CopyBuffer(atr_handle, 0, 0, smooth+1, atr_buffer) != smooth+1) return 0;

    double satr = 0;
    for(int i = 0; i < smooth; i++) satr += atr_buffer[i];
    satr /= smooth;

    // 2. Get Fixed Value por sessão
    datetime current_time = TimeGMT();
    MqlDateTime dt;
    TimeToStruct(current_time, dt);
    int hour_gmt = dt.hour;

    double fixed_value = 0.12; // Default
    if(hour_gmt >= 0 && hour_gmt < 8) fixed_value = 0.08;       // Asian
    else if(hour_gmt >= 8 && hour_gmt < 13) fixed_value = 0.14; // London
    else if(hour_gmt >= 13 && hour_gmt < 17) fixed_value = 0.18; // Overlap
    else if(hour_gmt >= 17 && hour_gmt < 22) fixed_value = 0.12; // NY PM

    // 3. Blend
    return SATR_Weight * satr + Fixed_Weight * fixed_value;
}

PLANO_C_FIXED_TABLE_ONLY.codigo_mql5_implementacao:
// Lookup table simples
static double g_session_vol[5] = {0.08, 0.14, 0.18, 0.12, 0.09};

double GetSessionVolatility() {
    datetime current = TimeGMT();
    MqlDateTime dt;
    TimeToStruct(current, dt);
    int h = dt.hour;

    if(h >= 0 && h < 8) return g_session_vol[0];       // Asian
    else if(h >= 8 && h < 13) return g_session_vol[1];  // London
    else if(h >= 13 && h < 17) return g_session_vol[2]; // Overlap
    else if(h >= 17 && h < 22) return g_session_vol[3]; // NY PM
    else return g_session_vol[4];                       // Night
}

sistema_hibrido_adaptativo.codigo_mql5:
double GetAdaptiveVolatility(string symbol, ENUM_TIMEFRAMES tf) {
    // 1. Detectar regime
    int adx_handle = iADX(symbol, tf, 14);
    double adx[1];
    CopyBuffer(adx_handle, 0, 0, 1, adx);

    double current_vol = CalculateRogersS atchell(symbol, tf, 14);
    double avg_vol = GetAverageVolatility(symbol, tf, 20);

    // 2. Aplicar regras
    if(current_vol > 2.0 * avg_vol) {
        return GetSessionVolatility(); // Fixed Table
    }
    else if(adx[0] > 25) {
        return CalculateRogersS atchell(symbol, tf, 14);
    }
    else if(adx[0] < 20) {
        return CalculateParkinson(symbol, tf, 14);
    }
    else {
        return CalculateSATR Blend(symbol, tf, 10, 5);
    }
}
